// Golden values generated by running the reference Python
// implementation (hashlib) for these exact inputs.
func TestComputeSearchSignatureGolden(t *testing.T) {
	got := computeSearchSignature("company=Exness&code=mt5")
	want := "5633975da435f0c4378e705c6abd3c15"
	if got != want {
		t.Fatalf("signature = %s, want %s", got, want)
	}
}

func TestLCGTIDGolden(t *testing.T) {
	got := lcgTID(123456789)
	want := "E06F7935F2FE2A50"
	if got != want {
		t.Fatalf("tid = %s, want %s", got, want)
	}
}

const sampleDirectoryJSON = `{"result":[{"company":"Exness","results":[
	{"name":"Exness-MT5Trial17","site":"https://www.exness.com","access":["13.213.81.113:443"],"is_demo":1},
	{"name":"Exness-MT5Real","site":"https://www.exness.com","access":["203.0.113.7:443"],"is_demo":0}
]}]}`

func TestSearchMQAgainstStub(t *testing.T) {
	var gotBody, gotUA, gotCookie string
	srv := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		b, _ := io.ReadAll(r.Body)
		gotBody = string(b)
		gotUA = r.Header.Get("User-Agent")
		gotCookie = r.Header.Get("Cookie")
		io.WriteString(w, "prefix-junk"+sampleDirectoryJSON)
	}))
	defer srv.Close()

	old := searchMQURL
	searchMQURL = srv.URL
	defer func() { searchMQURL = old }()

	companies, err := SearchMQ(context.Background(), "Exness", srv.Client())
	if err != nil {
		t.Fatalf("SearchMQ: %v", err)
	}
	if !strings.Contains(gotBody, "company=Exness&code=mt5&signature="+computeSearchSignature("company=Exness&code=mt5")+"&ver=2") {
		t.Fatalf("body = %s", gotBody)
	}
	if gotUA != searchUserAgent || !strings.Contains(gotCookie, "_fz_uniq=") || !strings.Contains(gotCookie, "tid=") {
		t.Fatalf("headers: UA=%q cookie=%q", gotUA, gotCookie)
	}
	if len(companies) != 1 || len(companies[0].Results) != 2 {
		t.Fatalf("companies = %+v", companies)
	}
	s := companies[0].Results[0]
	if s.Name != "Exness-MT5Trial17" || !s.IsDemo || s.Access[0] != "13.213.81.113:443" || s.Company != "Exness" {
		t.Fatalf("server = %+v", s)
	}
}

func TestSearchMT5IOAgainstStub(t *testing.T) {
	srv := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		io.WriteString(w, `[{"companyName":"Exness","results":[{"name":"Exness-MT5Trial17","access":["13.213.81.113:443"]}]}]`)
	}))
	defer srv.Close()

	old := searchMT5IO
	searchMT5IO = srv.URL
	defer func() { searchMT5IO = old }()

	companies, err := SearchMT5IO(context.Background(), "Exness", srv.Client())
	if err != nil {
		t.Fatalf("SearchMT5IO: %v", err)
	}
	if len(companies) != 1 || companies[0].Company != "Exness" ||
		len(companies[0].Results) != 1 || companies[0].Results[0].Access[0] != "13.213.81.113:443" {
		t.Fatalf("companies = %+v", companies)
	}
}

func TestFindServerFallbackAndMatch(t *testing.T) {
	oldMQ, oldSearch, oldIO := searchMQURL, searchURL, searchMT5IO
	defer func() { searchMQURL, searchURL, searchMT5IO = oldMQ, oldSearch, oldIO }()

	bad := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		http.Error(w, "down", http.StatusBadGateway)
	}))
	defer bad.Close()
	good := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		io.WriteString(w, sampleDirectoryJSON)
	}))
	defer good.Close()
	searchMQURL = bad.URL
	searchMT5IO = bad.URL
	searchURL = good.URL

	info, err := FindServer(context.Background(), "exness-mt5trial17", nil)
	if err != nil {
		t.Fatalf("FindServer: %v", err)
	}
	if info.Name != "Exness-MT5Trial17" {
		t.Fatalf("info = %+v", info)
	}

	if _, err := FindServer(context.Background(), "NoSuchServer", nil); err == nil {
		t.Fatal("expected not-found error")
	} else if !strings.Contains(err.Error(), "server not found") {
		t.Fatalf("err = %v", err)
	}
}
